#include "studio_legacy_media.h"
#include "studio_palette.h"
#include <filesystem>
#include <fstream>
#include <chrono>
#include <iostream>
using Bytes=std::vector<unsigned char>;
static int failures=0;
#define CHECK(x) do{if(!(x)){std::cerr<<"FAIL "<<__LINE__<<": " #x " / "<<error<<"\n";++failures;}}while(0)
static void word(Bytes &b,unsigned n){b.push_back((unsigned char)(n>>8));b.push_back((unsigned char)n);}
static void dword(Bytes &b,unsigned n){for(int i=24;i>=0;i-=8)b.push_back((unsigned char)(n>>i));}
static void chunk(Bytes &b,const char *tag,const Bytes &v){b.insert(b.end(),tag,tag+4);dword(b,(unsigned)v.size());b.insert(b.end(),v.begin(),v.end());if(v.size()&1)b.push_back(0);}
static Bytes palette(int n){Bytes p;for(int i=0;i<n;++i){p.push_back((unsigned char)(i<32?255-i*8:255));p.push_back((unsigned char)(i<32?i*8:0));p.push_back((unsigned char)(i<32?255-i*3:255));}return p;}
static Bytes fixture(const Bytes &colors,bool rle=false,int mask=0,unsigned mode=0x80,int planes=6,bool packed=false){
    Bytes b={'F','O','R','M',0,0,0,0};const char *tag=packed?"PBM ":"ILBM";b.insert(b.end(),tag,tag+4);Bytes header;word(header,64);word(header,2);word(header,0);word(header,0);header.insert(header.end(),{(unsigned char)planes,(unsigned char)mask,(unsigned char)rle,0});word(header,33);header.insert(header.end(),{1,1});word(header,64);word(header,2);chunk(b,"BMHD",header);chunk(b,"CMAP",colors);Bytes camg;dword(camg,mode);chunk(b,"CAMG",camg);chunk(b,"GRAB",{255,249,0,13});Bytes body;
    for(int y=0;y<2;++y)for(int p=0;p<planes+(mask==1);++p){Bytes row(8);for(int x=0;x<64;++x){int index=y?63-x:x;bool on=p==planes?((x+y)%3!=0):((index>>p)&1)!=0;if(on)row[x/8]|=(unsigned char)(128>>(x&7));}if(rle){body.push_back(128);body.push_back(7);}body.insert(body.end(),row.begin(),row.end());}chunk(b,"BODY",body);unsigned n=(unsigned)b.size()-8;for(int i=0;i<4;++i)b[4+i]=(unsigned char)(n>>(24-i*8));return b;
}
static Bytes read(const std::filesystem::path &p){std::ifstream f(p,std::ios::binary);return {std::istreambuf_iterator<char>(f),{}};}
int main(){using namespace studio;namespace fs=std::filesystem;std::string error;IndexedMedia m;auto colors=palette(32),input=fixture(colors);CHECK(decode_indexed_media(input,LegacyMediaKind::Lbm,m,error));CHECK(m.w==64&&m.h==2&&m.words.size()==64&&m.anchor_x==-7&&m.anchor_y==13&&m.note.find("Halfbrite")!=std::string::npos);if(m.words.size()!=64)return 1;
    for(int i=0;i<32;++i){unsigned full=(colors[i*3]>>3)*1024+(colors[i*3+1]>>3)*32+(colors[i*3+2]>>3);unsigned half=(colors[i*3]>>4)*1024+(colors[i*3+1]>>4)*32+(colors[i*3+2]>>4);CHECK(m.words[i]==full&&m.words[i+32]==half);}for(int x=0;x<64;++x)CHECK(m.pixels[x]==x&&m.pixels[64+x]==63-x);
    auto original=m;for(bool rle:{false,true}){CHECK(decode_indexed_media(fixture(colors,rle),LegacyMediaKind::Lbm,m,error)&&m.pixels==original.pixels&&m.words==original.words);CHECK(decode_indexed_media(fixture(palette(256),rle),LegacyMediaKind::Lbm,m,error)&&m.words==original.words&&m.pixels==original.pixels&&m.note.find("upper palette")!=std::string::npos);}
    for(int mask:{1,2})for(bool rle:{false,true}){CHECK(decode_indexed_media(fixture(colors,rle,mask),LegacyMediaKind::Lbm,m,error));for(int y=0;y<2;++y)for(int x=0;x<64;++x){int source=y?63-x:x;bool visible=mask==1?(x+y)%3!=0:source!=33;unsigned index=m.pixels[y*64+x];CHECK(visible?index!=0&&m.words[index]==original.words[source]:index==0);}CHECK(m.note.find("Opaque color zero moved")!=std::string::npos);}
    // Every malformed input leaves the caller's previous preview intact.
    auto reject=[&](const Bytes &b){m=original;CHECK(!decode_indexed_media(b,LegacyMediaKind::Lbm,m,error)&&m.words==original.words&&m.pixels==original.pixels);};for(size_t n=0;n<input.size();++n)reject(Bytes(input.begin(),input.begin()+n));for(int n:{1,16,31})reject(fixture(palette(n)));for(int planes:{1,5,7,8})reject(fixture(colors,false,0,0x80,planes));reject(fixture(colors,false,0,0x80,8,true));reject(fixture(colors,false,0,0x880));reject(fixture(colors,false,0,0x800));auto duplicate=input;chunk(duplicate,"CAMG",{0,0,0,128});unsigned total=(unsigned)duplicate.size()-8;for(int i=0;i<4;++i)duplicate[4+i]=(unsigned char)(total>>(24-i*8));reject(duplicate);
    // Import uses existing palette matching, history and original-layout IMG
    // saving. Export stores the resolved colors as an ordinary indexed image.
    auto root=fs::temp_directory_path()/("studio-halfbrite-"+std::to_string(std::chrono::steady_clock::now().time_since_epoch().count()));fs::create_directories(root);auto art=Artwork::demo();auto path=root/"source.IMG";CHECK(art->save(path.u8string(),error));auto raw=read(path);auto count=art->count(),pals=art->palette_count();auto version=art->disk_version();auto generation=art->generation();ImportBatch batch;CHECK(build_indexed_import(*art,original,"HALFBRITE",-1,-7,13,batch,error)&&art->generation()==generation&&art->count()==count&&!art->dirty());CHECK(art->import_batch(batch,error)==count&&art->palette_count()==pals+1&&copy_palette(*art,pals).words==original.words&&art->copy(count,0,0,64,2).pixels==original.pixels&&art->disk_version()==version);CHECK(art->save((root/"import.IMG").u8string(),error));auto loaded=Artwork::open((root/"import.IMG").u8string(),error);CHECK(loaded&&loaded->disk_version()==version&&copy_palette(*loaded,pals).words==original.words&&loaded->copy(count,0,0,64,2).pixels==original.pixels);art->undo();CHECK(art->count()==count&&art->palette_count()==pals);art->redo();CHECK(art->count()==count+1);CHECK(build_indexed_import(*art,original,"MATCHED",0,0,0,batch,error)&&art->import_batch(batch,error)==count+1&&art->palette_count()==pals+1);art->undo();for(auto kind:{LegacyMediaKind::Lbm,LegacyMediaKind::Tga}){Bytes encoded;IndexedMedia decoded;CHECK(encode_indexed_media(original,kind,encoded,error)&&decode_indexed_media(encoded,kind,decoded,error)&&decoded.words==original.words&&decoded.pixels==original.pixels);}CHECK(read(path)==raw);fs::remove_all(root);std::cout<<"Halfbrite: "<<failures<<" failures\n";return failures?1:0;
}
